export function redactAudit(value: unknown): unknown {
  return redact(value, new WeakMap<object, unknown>());
}

const SENSITIVE_KEYS = new Set(['password', 'token', 'secret']);
const REDACTED = '[REDACTED]';

function redact(value: unknown, copies: WeakMap<object, unknown>): unknown {
  if (Array.isArray(value)) {
    const existing = copies.get(value);
    if (existing !== undefined) return existing;

    const copy: unknown[] = new Array(value.length);
    copies.set(value, copy);

    for (let index = 0; index < value.length; index += 1) {
      if (index in value) copy[index] = redact(value[index], copies);
    }

    return copy;
  }

  if (!isPlainObject(value)) return value;

  const existing = copies.get(value);
  if (existing !== undefined) return existing;

  const copy: Record<string, unknown> = Object.create(Object.getPrototypeOf(value));
  copies.set(value, copy);

  for (const [key, entry] of Object.entries(value)) {
    copy[key] = SENSITIVE_KEYS.has(key.toLowerCase())
      ? REDACTED
      : redact(entry, copies);
  }

  return copy;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object') return false;

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

